 foreach(ObjectId id in (BlockTable)t.GetObject(source.BlockTableId,OpenMode.ForRead)){var b=(BlockTableRecord)t.GetObject(id,OpenMode.ForRead);if(!b.IsFromExternalReference||b.IsUnloaded)continue;var child=b.GetXrefDatabase(false);if(child!=null)Assets(child,visited,found);}
